document.addEventListener('DOMContentLoaded', () => {
const tooltipTriggerList = [].slice.call(document.querySelectorAll('[data-bs-toggle="tooltip"]'));
tooltipTriggerList.map(tooltipTriggerEl => new bootstrap.Tooltip(tooltipTriggerEl));
setupCodeCopy();
setupIndexFilters();
setupDestructiveDemo();
setupFalseAffordanceDemo();
});
function setupCodeCopy() {
document.querySelectorAll('.code-copy-btn').forEach(btn => {
btn.addEventListener('click', () => {
const targetId = btn.getAttribute('data-target');
const codeEl = document.getElementById(targetId);
if (codeEl) {
navigator.clipboard.writeText(codeEl.innerText).then(() => {
const originalText = btn.innerHTML;
btn.innerHTML = '<i class="bi bi-check2"></i> Copied!';
btn.classList.replace('btn-outline-light', 'btn-success');
setTimeout(() => {
btn.innerHTML = originalText;
btn.classList.replace('btn-success', 'btn-outline-light');
}, 2000);
});
}
});
});
}
function togglePasswordVisibility(inputId, btn) {
const input = document.getElementById(inputId);
if (!input) return;
const icon = btn.querySelector('i');
if (input.type === 'password') {
input.type = 'text';
btn.setAttribute('aria-label', 'Hide password');
if (icon) {
icon.classList.remove('bi-eye');
icon.classList.add('bi-eye-slash');
}
} else {
input.type = 'password';
btn.setAttribute('aria-label', 'Show password');
if (icon) {
icon.classList.remove('bi-eye-slash');
icon.classList.add('bi-eye');
}
}
}
function setupIndexFilters() {
const searchInput = document.getElementById('searchRules');
const pillarFilter = document.getElementById('filterPillar');
const tableRows = document.querySelectorAll('#matrixTable tbody tr');
if (!searchInput && !pillarFilter) return;
function filterTable() {
const query = (searchInput?.value || '').toLowerCase().trim();
const selectedPillar = pillarFilter?.value || 'all';
tableRows.forEach(row => {
const text = row.innerText.toLowerCase();
const pillar = row.getAttribute('data-pillar');
const matchesSearch = text.includes(query);
const matchesPillar = selectedPillar === 'all' || pillar === selectedPillar;
if (matchesSearch && matchesPillar) {
row.style.display = '';
} else {
row.style.display = 'none';
}
});
}
searchInput?.addEventListener('input', filterTable);
pillarFilter?.addEventListener('change', filterTable);
}
function setupDestructiveDemo() {
const phraseInput = document.getElementById('confirmPhraseInput');
const confirmBtn = document.getElementById('confirmDeleteSubmit');
if (phraseInput && confirmBtn) {
phraseInput.addEventListener('input', () => {
if (phraseInput.value.trim() === 'DELETE') {
confirmBtn.removeAttribute('disabled');
} else {
confirmBtn.setAttribute('disabled', 'true');
}
});
confirmBtn.addEventListener('click', () => {
const modalEl = document.getElementById('deleteConfirmModal');
const modal = bootstrap.Modal.getInstance(modalEl);
if (modal) modal.hide();
showToast('Account successfully purged. (Simulated safely with undo buffer)', 'warning');
});
}
}
function setupFalseAffordanceDemo() {
const deadClickables = document.querySelectorAll('.fake-button-affordance');
const counterEl = document.getElementById('deadClickCount');
let deadClicks = 0;
deadClickables.forEach(el => {
el.addEventListener('click', () => {
deadClicks++;
if (counterEl) {
counterEl.innerText = deadClicks;
}
showToast(`Dead Click detected on "${el.getAttribute('data-element-name') || 'Element'}"! No action was triggered.`, 'danger');
});
});
}
function showToast(message, type = 'primary') {
let container = document.getElementById('globalToastContainer');
if (!container) {
container = document.createElement('div');
container.id = 'globalToastContainer';
container.className = 'toast-container-custom';
document.body.appendChild(container);
}
const toastId = 'toast_' + Date.now();
const bgClass = type === 'danger' ? 'bg-danger text-white' : (type === 'warning' ? 'bg-warning text-dark' : 'bg-primary text-white');
const toastHtml = `
<div id="${toastId}" class="toast align-items-center ${bgClass} border-0 shadow" role="alert" aria-live="assertive" aria-atomic="true">
<div class="d-flex">
<div class="toast-body">
<i class="bi bi-info-circle-fill me-2"></i> ${message}
</div>
<button type="button" class="btn-close ${type === 'danger' || type === 'primary' ? 'btn-close-white' : ''} me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button>
</div>
</div>
`;
container.insertAdjacentHTML('beforeend', toastHtml);
const toastElement = document.getElementById(toastId);
const bsToast = new bootstrap.Toast(toastElement, { delay: 4000 });
bsToast.show();
toastElement.addEventListener('hidden.bs.toast', () => {
toastElement.remove();
});
}